"use client";

import Link from "next/link";
import { useParams, usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import { useUIStore } from "@/stores/ui.store";
import {
  LayoutDashboard,
  Database,
  Layers,
  Search,
  Settings,
  Server,
  Users,
  Microscope,
} from "lucide-react";

const menuItems = [
  {
    title: "Dashboard",
    icon: LayoutDashboard,
    href: (id: string) => `/${id}`,
    match: (path: string, id: string) => path === `/${id}`,
  },
  {
    title: "Indices",
    icon: Database,
    href: (id: string) => `/${id}/indices`,
    match: (path: string, id: string) => path.startsWith(`/${id}/indices`),
  },
  {
    title: "Collections",
    icon: Layers,
    href: (id: string) => `/${id}/collections`,
    match: (path: string, id: string) => path.startsWith(`/${id}/collections`),
  },
  {
    title: "Analysis",
    icon: Microscope,
    href: (id: string) => `/${id}/analysis/dictionary`,
    match: (path: string, id: string) => path.startsWith(`/${id}/analysis`),
  },
  {
    title: "Search",
    icon: Search,
    href: (id: string) => `/${id}/search/query-test`,
    match: (path: string, id: string) => path.startsWith(`/${id}/search`),
  },
  {
    title: "Management",
    icon: Settings,
    href: (id: string) => `/${id}/management/jdbc`,
    match: (path: string, id: string) => path.startsWith(`/${id}/management`),
  },
  {
    title: "Cluster",
    icon: Server,
    href: (id: string) => `/${id}/cluster`,
    match: (path: string, id: string) => path.startsWith(`/${id}/cluster`),
  },
  {
    title: "Users",
    icon: Users,
    href: (id: string) => `/${id}/users`,
    match: (path: string, id: string) => path.startsWith(`/${id}/users`),
  },
];

export function Sidebar() {
  const params = useParams();
  const pathname = usePathname();
  const { sidebarOpen } = useUIStore();
  const clusterId = params.clusterId as string;

  if (!sidebarOpen) return null;
  if (!clusterId) return null; // Or show loading/placeholder

  return (
    <div className="w-64 border-r bg-background h-screen flex flex-col">
      <div className="h-16 flex items-center px-6 border-b">
        <span className="font-bold text-lg">DSearch Console</span>
      </div>
      <div className="flex-1 py-4 overflow-y-auto">
        <nav className="space-y-1 px-2">
          {menuItems.map((item) => (
            <Link
              key={item.title}
              href={item.href(clusterId)}
              className={cn(
                "flex items-center px-4 py-2 text-sm font-medium rounded-md transition-colors",
                item.match(pathname, clusterId)
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
              )}
            >
              <item.icon className="mr-3 h-5 w-5" />
              {item.title}
            </Link>
          ))}
        </nav>
      </div>
      <div className="p-4 border-t">
        <div className="text-xs text-muted-foreground text-center">
          v2.0.0
        </div>
      </div>
    </div>
  );
}

