'use client';

import { useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { useClusterStore } from '@/stores/cluster.store';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ExternalLink, Settings } from 'lucide-react';
import Link from 'next/link';

export default function QueryTestPage() {
  const params = useParams();
  const router = useRouter();
  const clusterId = params.clusterId as string;
  const { currentCluster } = useClusterStore();

  // If Kibana is configured, redirect to Kibana
  useEffect(() => {
    if (currentCluster?.kibana) {
      let kibanaUrl = currentCluster.kibana;
      if (!kibanaUrl.startsWith('http://') && !kibanaUrl.startsWith('https://')) {
        kibanaUrl = `http://${kibanaUrl}`;
      }
      window.open(kibanaUrl, '_blank');
    }
  }, [currentCluster?.kibana]);

  if (currentCluster?.kibana) {
    let kibanaUrl = currentCluster.kibana;
    if (!kibanaUrl.startsWith('http://') && !kibanaUrl.startsWith('https://')) {
      kibanaUrl = `http://${kibanaUrl}`;
    }

    return (
      <div className="space-y-6">
        <div>
          <h1 className="text-2xl font-bold">쿼리 테스트</h1>
          <p className="text-muted-foreground">Kibana Dev Tools를 통해 쿼리를 테스트합니다.</p>
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ExternalLink className="h-5 w-5" />
              Kibana Dev Tools
            </CardTitle>
            <CardDescription>
              Kibana가 설정되어 있어 자동으로 새 탭에서 열립니다.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-4">
              <Button asChild>
                <a href={kibanaUrl} target="_blank" rel="noopener noreferrer">
                  <ExternalLink className="mr-2 h-4 w-4" />
                  Kibana 열기
                </a>
              </Button>
              <span className="text-sm text-muted-foreground">
                URL: {kibanaUrl}
              </span>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold">쿼리 테스트</h1>
        <p className="text-muted-foreground">Elasticsearch 쿼리를 테스트합니다.</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Settings className="h-5 w-5" />
            Kibana 설정 필요
          </CardTitle>
          <CardDescription>
            쿼리 테스트를 위해 Kibana를 설정해주세요.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Kibana가 설정되지 않았습니다. 클러스터 설정에서 Kibana URL을 설정하면
              Dev Tools를 통해 쿼리를 테스트할 수 있습니다.
            </p>
            <Button asChild variant="outline">
              <Link href={`/${clusterId}/cluster`}>
