import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import { Toaster } from "@/components/ui/sonner";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "DSearch Console v2",
  description: "Elasticsearch Cluster Management Console",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body
        className={`${geistSans.variable} ${geistMono.variable} antialiased`}
      >
        {children}
        <Toaster />
      </body>
    </html>
  );
}

"use client";

import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Server } from "lucide-react";

export default function Home() {
  // Mock Clusters
  const clusters = [
    { id: "dev-cluster", name: "Development Cluster", host: "192.168.1.10" },
    { id: "prod-cluster", name: "Production Cluster", host: "192.168.1.20" },
  ];

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-muted/20">
      <div className="max-w-2xl w-full space-y-8 p-4">
        <div className="text-center space-y-2">
          <h1 className="text-3xl font-bold">Welcome to DSearch Console v2</h1>
          <p className="text-muted-foreground">Select a cluster to manage</p>
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          {clusters.map((cluster) => (
            <Link key={cluster.id} href={`/${cluster.id}`}>
              <Card className="hover:bg-accent transition-colors cursor-pointer h-full">
                <CardHeader className="flex flex-row items-center space-y-0 pb-2 gap-3">
                  <div className="p-2 bg-primary/10 rounded-full">
                    <Server className="h-6 w-6 text-primary" />
                  </div>
                  <CardTitle className="text-base">{cluster.name}</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-sm text-muted-foreground">
                    ID: {cluster.id}
                  </div>
                  <div className="text-sm text-muted-foreground">
                    Host: {cluster.host}
                  </div>
                </CardContent>
              </Card>
            </Link>
          ))}
        </div>

        <div className="text-center">
             <Link href="/login">
                <Button variant="link">Go to Login</Button>
             </Link>
        </div>
      </div>
    </div>
  );
}

